import requests
import io
from pdfminer.high_level import extract_text_to_fp
from pdfminer.layout import LAParams

@triform.entrypoint
def action(input):
    pdf_url = input.get("url")
    if not pdf_url:
        return {"error": "No pdf url provided"}
    try:
        response = requests.get(pdf_url)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        return {"error": f"Failed to fetch PDF from URL: {str(e)}"}
    pdf_file = io.BytesIO(response.content)
    output_string = io.StringIO()
    try:
        laparams = LAParams()
        extract_text_to_fp(pdf_file, output_string, laparams=laparams, output_type='text', codec='utf-8')
    except Exception as e:
        return {"error": "Failed to extract text from PDF"}
    extracted_text = output_string.getvalue()
    return {"text": extracted_text}
